import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import ProgressBar from './Progressbar'; // Import the custom progress bar component
import '../styles/ProjectDetail.css';
import { format, parseISO } from 'date-fns'; // Importing functions from date-fns

import { exportToExcel } from '../utils/exportToExcel'; // Adjust the path based on your directory structure

const ProjectDetail = () => {
  const { projectId } = useParams();
  const navigate = useNavigate();

  const [projectDetails, setProjectDetails] = useState({
    projectName: '',
    client: '',
    contractor: '',
    consultant: '',
    title: ''
  });
  const [sections, setSections] = useState([]);
  const [newSectionName, setNewSectionName] = useState('');
  const [newSubsectionName, setNewSubsectionName] = useState('');
  const [currentSectionId, setCurrentSectionId] = useState(null);
  const [currentSubsectionId, setCurrentSubsectionId] = useState(null);
  const [isSectionModalOpen, setIsSectionModalOpen] = useState(false);
  const [isSubsectionModalOpen, setIsSubsectionModalOpen] = useState(false);
  const [isDocumentModalOpen, setIsDocumentModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [newDocumentName, setNewDocumentName] = useState('');
  const [editingDocument, setEditingDocument] = useState(null);
  const [documents, setDocuments] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [overallProgress, setOverallProgress] = useState('0'); // State for overall progress

  useEffect(() => {
    const fetchData = async () => {
      if (projectId) {
        const success = await fetchProjectDetails();
        if (success) {
          console.log('Details fetched');
        } else {
          console.log('No details fetched');
        }
      }
    };
    fetchData();
  }, [projectId]);

  useEffect(() => {
    fetchDocuments();
  }, [projectId]); // Fetch documents when projectId changes

  useEffect(() => {
    // Calculate overall progress whenever documents change
    const calculateOverallProgress = () => {
      if (documents.length === 0) {
        return '0'; // No documents, no progress
      }

      const validDocuments = documents.filter(document => typeof document.progress === 'number' && !isNaN(document.progress));

      if (validDocuments.length === 0) {
        return '0'; // No valid progress values found
      }
      const totalProgress = validDocuments.reduce((sum, document) => sum + document.progress, 0);
      const averageProgress = totalProgress / validDocuments.length;
      return averageProgress.toFixed(2); // Average progress
    };

    setOverallProgress(calculateOverallProgress());
  }, [documents]);

  const fetchProjectDetails = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/api/projects/${projectId}`);
      const projectData = response.data;
      setProjectDetails({
        projectName: capitalizeFirstLetter(projectData.project_name),
        client: projectData.client,
        contractor: projectData.contractor,
        consultant: projectData.consultant,
        title: projectData.title
      });
      await fetchSections(Number(projectId));
      return true;
    } catch (error) {
      console.error('Error fetching project details:', error);
      return false;
    }
  };

  const fetchSections = async (numericProjectId) => {
    try {
      const sectionsResponse = await axios.get(`http://localhost:5000/api/projects/${numericProjectId}/sections`);
      const sectionsWithSubsections = await Promise.all(sectionsResponse.data.map(async (section) => {
        const subsectionsResponse = await axios.get(`http://localhost:5000/api/sections/${section.section_id}/subsections`);
        const subsectionsWithDocuments = await Promise.all(subsectionsResponse.data.map(async (subsection) => {
          const documentsResponse = await axios.get(`http://localhost:5000/api/subsections/${subsection.subsection_id}/documents`);
          return { ...subsection, documents: documentsResponse.data };
        }));
        return { ...section, subsections: subsectionsWithDocuments };
      }));
      setSections(sectionsWithSubsections);
    } catch (error) {
      console.error('Error fetching sections:', error);
      throw error;
    }
  };

  const refetchProjectDetails = async () => {
    try {
      await fetchProjectDetails();
      await fetchDocuments(); // Fetch documents after updating project details
    } catch (error) {
      console.error('Error refetching project details:', error);
    }
  };

  const handleAddSection = async () => {
    try {
      const numericProjectId = Number(projectId);
      await axios.post('http://localhost:5000/api/sections', { section_name: capitalizeFirstLetter(newSectionName), project_id: numericProjectId });
      setNewSectionName('');
      setIsSectionModalOpen(false);
      refetchProjectDetails();
    } catch (error) {
      console.error('Error adding section:', error);
    }
  };

  const handleAddSubsection = async () => {
    try {
      await axios.post('http://localhost:5000/api/subsections', { subsection_name: capitalizeFirstLetter(newSubsectionName), section_id: currentSectionId, project_id: projectId });
      setNewSubsectionName('');
      setIsSubsectionModalOpen(false);
      refetchProjectDetails();
    } catch (error) {
      console.error('Error adding subsection:', error);
    }
  };

  const handleSubmitDocument = async (e) => {
    e.preventDefault();
    try {
      const section = sections.find((section) => section.section_id === currentSectionId);
      const subsection = section.subsections.find((subsection) => subsection.subsection_id === currentSubsectionId);

      await axios.post('http://localhost:5000/api/documents', {
        document_name: capitalizeFirstLetter(newDocumentName),
        subsection_id: currentSubsectionId,
        section_id: currentSectionId,
        project_id: projectId,
        start_date: null, // Add start_date, end_date, status, priority, assigned_to, and progress
        end_date: null,
        status: null,
        priority: null,
        assigned_to: null,
        progress: 0,
        section_name: section.section_name,
        subsection_name: subsection.subsection_name
      });
      setNewDocumentName('');
      setIsDocumentModalOpen(false);
      refetchProjectDetails();
    } catch (error) {
      console.error('Error adding document:', error);
    }
  };

  const handleDeleteSection = async (sectionId) => {
    try {
      await axios.delete(`http://localhost:5000/api/sections/${sectionId}`); // Delete section
      refetchProjectDetails(); // Refetch project details
    } catch (error) {
      console.error('Error deleting section:', error);
    }
  };

  const handleDeleteSubsection = async (subsectionId) => {
    try {
      await axios.delete(`http://localhost:5000/api/subsections/${subsectionId}`); // Delete subsection
      refetchProjectDetails(); // Refetch project details
    } catch (error) {
      console.error('Error deleting subsection:', error);
    }
  };

  const handleDeleteDocument = async (documentId, subsectionId) => {
    try {
      console.log('Deleting document with ID:', documentId, 'in subsection ID:', subsectionId);
      await axios.delete(`http://localhost:5000/api/documents/${documentId}/${subsectionId}`, {
        data: { section_id: currentSectionId, project_id: projectId } // Include section_id and project_id in the delete request
      });
      refetchProjectDetails(); // Refetch project details
    } catch (error) {
      console.error('Error deleting document:', error);
    }
  };

  const handleEditDocument = (document) => {
    // Format dates using date-fns
    const formattedDocument = {
      ...document,
      start_date: document.start_date ? format(parseISO(document.start_date), 'yyyy-MM-dd') : '',
      end_date: document.end_date ? format(parseISO(document.end_date), 'yyyy-MM-dd') : '',
      document_id: document.document_id // Ensure document_id is included
    };
    setEditingDocument(formattedDocument);
    setIsEditModalOpen(true);
  };

  const handleSaveDocument = async (e) => {
    e.preventDefault();
    try {
      // Format the dates before sending to the backend
      const formattedDocument = {
        ...editingDocument,
        start_date: editingDocument.start_date ? format(parseISO(editingDocument.start_date), 'yyyy-MM-dd') : '',
        end_date: editingDocument.end_date ? format(parseISO(editingDocument.end_date), 'yyyy-MM-dd') : ''
      };
      await axios.put(`http://localhost:5000/api/documents/${editingDocument.document_id}`, formattedDocument);
      setIsEditModalOpen(false);
      setEditingDocument(null);
      refetchProjectDetails(); // Refetch project details
    } catch (error) {
      console.error('Error saving document:', error);
    }
  };

  const handleExportToExcel = () => {
    // Utilize the exportToExcel function passing necessary parameters
    exportToExcel(projectDetails.projectName, sections);
  };

  const handleSearchChange = (event) => {
    setSearchTerm(event.target.value);
  };

  const handleSearch = () => {
    const results = documents.filter(document =>
      document.document_name.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setSearchResults(results);
  };

  const capitalizeFirstLetter = (string) => {
    return string.charAt(0).toUpperCase() + string.slice(1);
  };

  const fetchDocuments = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/api/projects/${projectId}/documents`);
      setDocuments(response.data);
    } catch (error) {
      console.error('Error fetching documents:', error);
    }
  };

  return (
    <div className="project-detail">
      <div className="project-detail-header">
        <h2>{projectDetails.projectName}</h2>
        <div className="project-info">
          <p>Client: {projectDetails.client}</p>
          <p>Contractor: {projectDetails.contractor}</p>
          <p>Consultant: {projectDetails.consultant}</p>
          <p>Title: {projectDetails.title}</p>
        </div>
      </div>

      <div className="progress-bar">
        <ProgressBar progress={overallProgress} />
      </div>

      <div className="section-container">
        {sections.map(section => (
          <div key={section.section_id} className="section">
            <h3>{section.section_name}</h3>
            {section.subsections.map(subsection => (
              <div key={subsection.subsection_id} className="subsection">
                <h4>{subsection.subsection_name}</h4>
                <ul>
                  {subsection.documents.map(document => (
                    <li key={document.document_id}>
                      <span>{document.document_name}</span>
                      <button onClick={() => handleDeleteDocument(document.document_id, subsection.subsection_id)}>Delete</button>
                      <button onClick={() => handleEditDocument(document)}>Edit</button>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
            <button onClick={() => { setCurrentSectionId(section.section_id); setIsSubsectionModalOpen(true); }}>Add Subsection</button>
            <button onClick={() => { setCurrentSectionId(section.section_id); setIsDocumentModalOpen(true); }}>Add Document</button>
            <button onClick={() => handleDeleteSection(section.section_id)}>Delete Section</button>
          </div>
        ))}
        <button onClick={() => setIsSectionModalOpen(true)}>Add Section</button>
      </div>

      <div className="modal">
        {isSectionModalOpen && (
          <div className="modal-content">
            <h3>Add Section</h3>
            <input type="text" value={newSectionName} onChange={(e) => setNewSectionName(e.target.value)} placeholder="Section Name" />
            <button onClick={handleAddSection}>Add Section</button>
            <button onClick={() => setIsSectionModalOpen(false)}>Cancel</button>
          </div>
        )}

        {isSubsectionModalOpen && (
          <div className="modal-content">
            <h3>Add Subsection</h3>
            <input type="text" value={newSubsectionName} onChange={(e) => setNewSubsectionName(e.target.value)} placeholder="Subsection Name" />
            <button onClick={handleAddSubsection}>Add Subsection</button>
            <button onClick={() => setIsSubsectionModalOpen(false)}>Cancel</button>
          </div>
        )}

        {isDocumentModalOpen && (
          <div className="modal-content">
            <h3>Add Document</h3>
            <input type="text" value={newDocumentName} onChange={(e) => setNewDocumentName(e.target.value)} placeholder="Document Name" />
            <button onClick={handleSubmitDocument}>Add Document</button>
            <button onClick={() => setIsDocumentModalOpen(false)}>Cancel</button>
          </div>
        )}

        {isEditModalOpen && (
          <div className="modal-content">
            <h3>Edit Document</h3>
            <form onSubmit={handleSaveDocument}>
              <input type="text" value={editingDocument ? editingDocument.document_name : ''} onChange={(e) => setEditingDocument({ ...editingDocument, document_name: e.target.value })} placeholder="Document Name" />
              <input type="date" value={editingDocument ? editingDocument.start_date : ''} onChange={(e) => setEditingDocument({ ...editingDocument, start_date: e.target.value })} placeholder="Start Date" />
              <input type="date" value={editingDocument ? editingDocument.end_date : ''} onChange={(e) => setEditingDocument({ ...editingDocument, end_date: e.target.value })} placeholder="End Date" />
              <input type="number" value={editingDocument ? editingDocument.progress : ''} onChange={(e) => setEditingDocument({ ...editingDocument, progress: e.target.value })} placeholder="Progress" />
              <button type="submit">Save Changes</button>
            </form>
            <button onClick={() => setIsEditModalOpen(false)}>Cancel</button>
          </div>
        )}
      </div>

      <div className="search-container">
        <input type="text" value={searchTerm} onChange={handleSearchChange} placeholder="Search Documents" />
        <button onClick={handleSearch}>Search</button>
      </div>

      <div className="search-results">
        <h3>Search Results</h3>
        <ul>
          {searchResults.map(document => (
            <li key={document.document_id}>{document.document_name}</li>
          ))}
        </ul>
      </div>

      <button onClick={handleExportToExcel}>Export to Excel</button>
      <button onClick={() => navigate('/projects')}>Back to Projects</button>
    </div>
  );
};

export default ProjectDetail;
